            d=months(first,m); lo=d-datetime.timedelta(days=30); hi=d+datetime.timedelta(days=30)
            if hi>=EVAL: continue
            hits=[]
            for s in rs:
                if s['resourceType']!='Specimen': continue
                c=dt(s['collection']['collectedDateTime'])
                if not (lo<=c<=hi): continue
                for o in obsby[s['id']]:
                    if 'RPR' in o['code']['text'] or 'VDRL' in o['code']['text']:
                        hits.append('%s %s %s owner=%s chart=%s'%(c.date(),o['id'],o['status'],specstatus(s,p),sub(o)))
            L.append('  FU %dmo due %s win %s..%s CLOSED hits=%s'%(m,d.date(),lo.date(),hi.date(),hits or 'NONE'))
    else:
        L.append('  FU: no completed clinic dose')
    return '\n'.join(L)
if __name__=='__main__':
    ids=sys.argv[1:] or sorted(pats)
    for pid in ids: print(rpt(pid)); print()
